"""A fake that lies about *which* objects it touched, never about how many (checkpoint B1).

`FakeMcp` covers servers that misreport a field or a count. The failure this file models is
invisible to both: every count lands exactly where the caller said it would, and only the
identity of what exists has moved. Each switch is one scenario the review reproduced.

Split from `fake_tree.py` rather than added to it because that module is already at the
length this repo's hooks accept, and because these tools share one theme: the report is
word-for-word true and still describes work that did not happen to the named object.
"""

from __future__ import annotations

from typing import Any

from harness.mcp_session import ToolResult

from .fake_tree import FakeMcp

# The person a delete that lost its query filter would reach instead — `people[0]`
# (`get_person`, gramps_client.py:620), never the one the caller named.
FIRST_PERSON = "I0000"
RENUMBERED = "I0042"


class FakeIdentityMcp(FakeMcp):
    """`FakeMcp` plus the four ways a call can move identity while the counts agree."""

    def __init__(self, tree: Any) -> None:
        super().__init__(tree)
        # Deletes `people[0]` and echoes back the id it was handed. Both halves of the
        # report stay literally correct: `gramps_id` is the argument (gramps_client.py:1078)
        # and `deleted: True` is a constant.
        self.delete_wrong_person = False
        # Creates the person, then hands back an id that already existed. It resolves, so
        # the lookup in `assert_new_id_resolves` is satisfied by the wrong record.
        self.stale_id = False
        # An import that also destroys and re-creates an unrelated family: one namespace
        # moves as expected, another churns to a net zero.
        self.swap_family = False
        # A gramps_id edited under an unchanged handle — no count moves, no id enters or
        # leaves the tree as a *handle*, and the object is a different one afterwards.
        self.renumber = False

    def _t_gramps_delete_person(self, gramps_id: str, confirm: bool = False) -> ToolResult:
        if not self.delete_wrong_person:
            return super()._t_gramps_delete_person(gramps_id, confirm)
        if not confirm:
            raise ValueError("delete_person requires confirm=True (destructive)")
        people = self.tree.namespaces["people"]
        count_before = len(people)
        people.pop(FIRST_PERSON)
        return self._dict_result(
            {
                "gramps_id": gramps_id,
                "deleted": True,
                "count_before": count_before,
                "count_after": len(people),
            }
        )

    def _t_gramps_add_person(self, first_name: str = "", surname: str = "") -> ToolResult:
        result = super()._t_gramps_add_person(first_name, surname)
        return self._str_result(FIRST_PERSON) if self.stale_id else result

    def _t_gramps_import_file(self, filename: str) -> ToolResult:
        """The counts in the report stay right: a swap and a renumber move neither total."""
        result = super()._t_gramps_import_file(filename)
        if self.swap_family:
            families = self.tree.namespaces["families"]
            families.pop("F0000")
            families["F0001"] = {
                "handle": "h-F0001",
                "gramps_id": "F0001",
                "child_ref_list": [],
            }
        if self.renumber:
            people = self.tree.namespaces["people"]
            record = people.pop("I0002")
            record["gramps_id"] = RENUMBERED  # the handle stays `h-I0002`
            people[RENUMBERED] = record
        return result

    def _t_gramps_delete_all_objects(
        self, confirm: bool = False, expected_count: int = -1
    ) -> ToolResult:
        """The shipped shape (`gramps_client.py:609-613`): `{before, after, deleted}` as counts.

        Named ids are hopeless here — that is what `EVERYTHING` is for.
        """
        before = self.tree.counts()
        total = sum(before.values())
        if not confirm:
            raise ValueError("delete_all_objects requires confirm=True (destructive)")
        if expected_count != total:
            raise ValueError(
                f"expected_count={expected_count} does not match the live total {total}"
            )
        for records in self.tree.namespaces.values():
            records.clear()
        after = self.tree.counts()
        return self._dict_result(
            {
                "before": before,
                "after": after,
                "deleted": {key: before[key] - after.get(key, 0) for key in before},
            }
        )
